import math
from collections import Counter

def knn_predict(train_x: list[list[float]], train_y: list[int], query: list[float], k: int) -> int:
    def dist(a: list[float]) -> float:
        return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, query)))
    ranked = sorted(((dist(x), i, train_y[i]) for i, x in enumerate(train_x)))
    votes = Counter(label for _, _, label in ranked[:k])
    return int(sorted(votes.items(), key=lambda kv: (-kv[1], kv[0]))[0][0])
